diff:
--- a/training/level-1/L1-027-env-parse/parseEnvMetadata.mjs
+++ b/training/level-1/L1-027-env-parse/parseEnvMetadata.mjs
@@ -0,0 +1,26 @@
+import { createRequire } from 'module';
+const require = createRequire(import.meta.url);
+const fs = require('fs');
+
+export function parseEnvMetadata(content) {
+  const seenNames = new Set();
+  const result = [];
+  
+  const lines = content.split('\n');
+  for (const line of lines) {
+    const trimmedLine = line.trim();
+    if (!trimmedLine) continue;
+    
+    // Match optional 'export' followed by whitespace and then variable name
+    const match = trimmedLine.match(/^export\s*(\w+)/);
+    if (!match) continue;
+    
+    const varName = match[1];
+    if (seenNames.has(varName)) continue;
+    
+    seenNames.add(varName);
+    result.push({ name: varName, present: true });
+  }
+  
+  return result;
+}

